#include <bits/stdc++.h>
using namespace std;

class Solution {public:int countTexts(string s){const int MOD=1000000007;int n=s.size();vector<int> dp(n+1);dp[0]=1;for(int i=1;i<=n;++i){int lim=(s[i-1]=='7'||s[i-1]=='9')?4:3;for(int j=1;j<=lim&&j<=i&&s[i-j]==s[i-1];++j){dp[i]=(dp[i]+dp[i-j])%MOD;}}return dp[n];} };
